import React from 'react';

import { editFundInModalAsync } from '@apps/Finances/components/FundEdit';
import FundsList from '@apps/Finances/components/FundsList';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import { AuthContext } from '@contexts/AuthContext';
import { success } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

const FundsPage = () => {
  const authContext = React.useContext(AuthContext);
  const handleAdd = () => {
    if (!authContext.user) return;

    editFundInModalAsync({
      id: 0,
      name: '',
      description: '',
      author: authContext.user,
      created_at: new Date(),
      is_active: false,
      is_public: false,
      updated_at: null,
      archived_at: null,
    }).then((up) => {
      success('Добавлено ' + up.name);
      window.location.reload();
    });
  };
  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/finances', text: 'Финансы' },
          { href: '/finances/funds', text: 'Фонды', active: true },
        ]}
      />
      <Page title={'Фонды'}>
        <PageHeader title={'Фонды'}>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleAdd}>
            Добавить
          </PohButton>
        </PageHeader>
        <FundsList />
      </Page>
    </PohContainer>
  );
};

export default FundsPage;
